const KEY='meu-fluxo-v1';
const now=new Date(); let current=new Date(now.getFullYear(),now.getMonth(),1);
const dateInMonth=n=>`${current.getFullYear()}-${String(current.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;
const examples=[['Salário','Trabalho','income',5000,5],['Aluguel','Moradia','fixed',1500,8],['Supermercado','Alimentação','variable',580,10],['Internet','Moradia','fixed',120,12],['Café e almoço','Alimentação','variable',85,15],['Reserva mensal','Reserva','saved',600,18],['Transporte','Transporte','variable',180,20]].map(([description,category,type,amount,day])=>({id:crypto.randomUUID(),description,category,type,amount,date:dateInMonth(day)}));
let data; try {const raw=localStorage.getItem(KEY); data=raw===null?examples:JSON.parse(raw);if(!Array.isArray(data))data=[]} catch{data=[]} localStorage.setItem(KEY,JSON.stringify(data));
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n), colors=['#719a78','#abc6a8','#dfbd9c','#c9bdcf','#e5d7ae','#92afa9'];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){let ym=dateInMonth(1).slice(0,7), entries=data.filter(x=>x.date.slice(0,7)===ym).sort((a,b)=>b.date.localeCompare(a.date)); const sum=t=>entries.filter(x=>t.includes(x.type)).reduce((n,x)=>n+Number(x.amount),0),income=sum(['income']),fixed=sum(['fixed']),variable=sum(['variable']),saved=sum(['saved']),expense=fixed+variable;
$('#month').textContent=current.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}); $('#balance').textContent=money(income-expense-saved);$('#income').textContent=money(income);$('#expenses').textContent=money(expense);$('#saved').textContent=money(saved);$('#expenseDetail').textContent=`${money(fixed)} fixos · ${money(variable)} variáveis`;$('#donutTotal').textContent=money(expense);$('#reserveTotal').textContent=money(data.filter(x=>x.type==='saved'&&x.date.slice(0,7)<=ym).reduce((n,x)=>n+Number(x.amount),0));
$('#list').innerHTML=entries.map(x=>`<div class="item"><div class="item-name"><span class="item-icon">${x.type==='income'?'↙':x.type==='saved'?'◇':'↗'}</span><span>${escapeHtml(x.description)}</span></div><div class="category"><span class="tag">${escapeHtml(x.category)}</span></div><span class="date">${x.date.slice(8,10)}/${x.date.slice(5,7)}</span><span class="money ${x.type==='income'?'positive':''}">${x.type==='income'?'+':'−'} ${money(x.amount)}</span><button class="delete" data-id="${escapeHtml(x.id)}" aria-label="Excluir ${escapeHtml(x.description)}">×</button></div>`).join('');$('#empty').hidden=entries.length>0;
let groups={};entries.filter(x=>['fixed','variable'].includes(x.type)).forEach(x=>groups[x.category]=(groups[x.category]||0)+Number(x.amount));let parts=Object.entries(groups).sort((a,b)=>b[1]-a[1]), at=0;$('#donut').style.background=expense?'conic-gradient('+parts.map(([_,v],i)=>{let start=at;at+=v/expense*100;return `${colors[i%colors.length]} ${start}% ${at}%`}).join(',')+')':'#e8efe8';$('#legend').innerHTML=parts.length?parts.map(([k,v],i)=>`<div class="legend-row"><i style="background:${colors[i%colors.length]}"></i>${escapeHtml(k)}<strong>${money(v)}</strong></div>`).join(''):'<div class="legend-row">Nenhuma despesa neste mês.</div>';
}
function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}
$('#previous').onclick=()=>{current.setMonth(current.getMonth()-1);render()};$('#next').onclick=()=>{current.setMonth(current.getMonth()+1);render()};document.querySelectorAll('.add').forEach(b=>b.onclick=()=>{$('#form').reset();$('#form').elements.date.value=dateInMonth(Math.min(now.getDate(),28));$('#dialog').showModal()});$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});$('#form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);let amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0)return;data.push({id:crypto.randomUUID(),description:f.get('description').trim(),category:f.get('category').trim(),type:f.get('type'),date:f.get('date'),amount});let d=f.get('date').split('-');current=new Date(Number(d[0]),Number(d[1])-1,1);save();$('#dialog').close()};$('#list').onclick=e=>{let btn=e.target.closest('[data-id]');if(btn&&confirm('Excluir este lançamento?')){data=data.filter(x=>x.id!==btn.dataset.id);save()}};render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
